\title{The Siegel--Weil Identity for the $E_8$ Theta Series and the Hecke
Structure of $240\,\sigma_3$}
\author{Aristotle}
\date{2026-07-12}

\begin{document}

\begin{abstract}
The theta series of an even, positive-definite, unimodular lattice of rank $8$
coincides with the normalized weight-$4$ Eisenstein series $E_4$. Equivalently,
writing $r(n)$ for the number of lattice vectors of squared length $2n$, one has
$r(n) = 240\,\sigma_3(n)$ for every positive integer $n$, where
$\sigma_3(n) = \sum_{d \mid n} d^3$. This is the foundational rank-$8$ case of
the classical Siegel--Weil formula, which equates the average theta series of a
genus of quadratic forms with an Eisenstein series; the genus of even unimodular
rank-$8$ lattices has a single class, so the average degenerates to the single
lattice $E_8$. We give a self-contained account of the arithmetic backbone of
this identity: the coefficient system $n \mapsto 240\,\sigma_3(n)$ is the
coefficient system of a Hecke eigenform. We establish a geometric closed form
for $\sigma_3$ at prime powers, the three-term Hecke recurrence on prime powers,
multiplicativity across coprime arguments and its consequence for representation
numbers, and the global Hecke eigenform convolution identity
$\sigma_3(m)\,\sigma_3(n) = \sum_{d \mid \gcd(m,n)} d^3\,\sigma_3(mn/d^2)$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Lattices, shells, and theta series}
A \emph{lattice} $L \subset \mathbb{R}^8$ is the set of integer linear
combinations of a basis; with the standard inner product it carries an
integer-valued quadratic form $x \mapsto \langle x, x\rangle$. The lattice is
\emph{even} if $\langle x,x\rangle \in 2\mathbb{Z}$ for all $x$,
\emph{positive-definite} if $\langle x,x\rangle > 0$ for $x \neq 0$, and
\emph{unimodular} if its Gram matrix has determinant $\pm 1$ (equivalently
$L = L^\ast$). In rank $8$ there is, up to isometry, exactly one even
positive-definite unimodular lattice: the root lattice $E_8$.

Partitioning $L$ into shells by squared length yields the \emph{representation
numbers} $N(k) = \#\{x \in L : \langle x, x\rangle = k\}$. For an even lattice
$N(k) = 0$ unless $k$ is even, so we index by $n$ with $k = 2n$ and write
$r(n) = N(2n)$. The \emph{theta series}
\[
\theta_L(\tau) = \sum_{x \in L} q^{\langle x,x\rangle/2} = \sum_{n \ge 0} r(n)\,q^n,
\qquad q = e^{2\pi i \tau},\ \mathrm{Im}\,\tau > 0,
\]
with $r(0) = 1$, is a modular form of weight $m/2$ for $\SL_2(\mathbb{Z})$ when
$L$ is even unimodular of rank $m$.

\subsection{The Eisenstein series $E_4$}
For even weight $k \ge 4$,
\[
E_k(\tau) = 1 - \frac{2k}{B_k}\sum_{n \ge 1}\sigma_{k-1}(n)\,q^n,
\qquad \sigma_{k-1}(n) = \sum_{d \mid n} d^{\,k-1}.
\]
With $B_4 = -1/30$ we get $E_4(\tau) = 1 + 240\sum_{n \ge 1}\sigma_3(n)\,q^n$. The
space $M_4(\SL_2(\mathbb{Z}))$ is one-dimensional, spanned by $E_4$, and contains
no nonzero cusp forms.

\subsection{The Siegel--Weil identity in rank 8}
Since $\theta_{E_8}$ is a weight-$4$ modular form with constant term $1$, and
$M_4$ is spanned by $E_4$ (also with constant term $1$),
\[
\theta_{E_8} = E_4 \qquad\Longleftrightarrow\qquad r(n) = 240\,\sigma_3(n)\ \
(n \ge 1).
\]
This is the rank-$8$ case of the Siegel--Weil formula, where the genus is a
single class. We write $\rE(n) := 240\,\sigma_3(n)$.

\section{Definitions}

\begin{definition}[Divisor-power sum]
For $s \in \mathbb{N}$ and $n \ge 1$, $\sigma_s(n) = \sum_{d \mid n} d^s$, with
$\sigma_s(0) = 0$. Each $\sigma_s$ is multiplicative:
$\sigma_s(mn) = \sigma_s(m)\sigma_s(n)$ when $\gcd(m,n)=1$.
\end{definition}

\begin{definition}[Siegel--Weil prediction]
The predicted number of $E_8$ vectors of squared length $2n$ is
$\rE(n) = 240\,\sigma_3(n)$.
\end{definition}

\begin{definition}[Hecke convolution]
For $m,n \ge 1$,
$\heckeRHS(m,n) = \sum_{d \mid \gcd(m,n)} d^3\,\sigma_3(mn/d^2)$, with
$\heckeRHS(0,n) = \heckeRHS(m,0) = 0$.
\end{definition}

\section{The arithmetic of $\sigma_3$ at prime powers}

\begin{theorem}[Prime-power closed form]\label{thm:pp}
For a prime $p$ and $r \ge 0$,
$\displaystyle \sigma_3(p^r) = \sum_{i=0}^{r} p^{3i}.$
\end{theorem}
\begin{proof}
The divisors of $p^r$ are $1, p, \dots, p^r$, so
$\sigma_3(p^r) = \sum_{j=0}^{r}(p^j)^3 = \sum_{j=0}^{r} p^{3j}$.
\end{proof}

\begin{corollary}[Value at a prime]\label{cor:prime}
$\sigma_3(p) = 1 + p^3$.
\end{corollary}
\begin{proof}
Take $r = 1$ in Theorem~\ref{thm:pp}.
\end{proof}

Summing the geometric series gives
$\sigma_3(p^r)(p^3 - 1) = p^{3(r+1)} - 1$.

\begin{theorem}[Hecke recurrence on prime powers]\label{thm:rec}
For a prime $p$ and $r \ge 0$,
\[
\sigma_3(p^{r+2}) + p^3\,\sigma_3(p^r) = \sigma_3(p)\,\sigma_3(p^{r+1}).
\]
\end{theorem}
\begin{proof}
Write $S_a = \sum_{i=0}^{a} p^{3i}$, so $\sigma_3(p^a) = S_a$ and
$\sigma_3(p) = S_1 = 1 + p^3$. The right side is
$(1 + p^3)S_{r+1} = S_{r+1} + p^3 S_{r+1}$. Now
$p^3 S_{r+1} = \sum_{j=1}^{r+2} p^{3j} = S_{r+2} - 1$ and
$S_{r+1} = S_r + p^{3(r+1)}$, so the right side equals
$S_{r+2} + S_r + p^{3(r+1)} - 1$. The left side is $S_{r+2} + p^3 S_r$. Equality
reduces to $(p^3 - 1)S_r = p^{3(r+1)} - 1$, the geometric-sum identity.
\end{proof}

The number $\sigma_3(p) = 1 + p^3$ is the eigenvalue of the Hecke operator $T_p$
on $E_4$; Theorem~\ref{thm:rec} is the coefficient-level shadow of
$T_p E_4 = (1 + p^3)E_4$.

\section{Multiplicativity and representation numbers}

\begin{theorem}[Multiplicativity]\label{thm:mult}
If $\gcd(m,n) = 1$ then $\sigma_3(mn) = \sigma_3(m)\,\sigma_3(n)$.
\end{theorem}
\begin{proof}
Divisors of $mn$ factor uniquely as $d = d_1 d_2$ with $d_1 \mid m$,
$d_2 \mid n$, giving a bijection $\Div(mn) \cong \Div(m)\times\Div(n)$. Hence
$\sigma_3(mn) = \sum_{d_1 \mid m}\sum_{d_2 \mid n}(d_1 d_2)^3
= \sigma_3(m)\sigma_3(n)$.
\end{proof}

\begin{corollary}[Quasi-multiplicativity of counts]\label{cor:qm}
For coprime $m,n$, $\;240\,\rE(mn) = \rE(m)\,\rE(n)$.
\end{corollary}
\begin{proof}
$240\,\rE(mn) = 240^2\sigma_3(mn) = (240\sigma_3(m))(240\sigma_3(n))
= \rE(m)\rE(n)$ by Theorem~\ref{thm:mult}.
\end{proof}

\section{The global Hecke eigenform identity}

\begin{theorem}[Hecke eigenform identity]\label{thm:hecke}
For all $m,n \ge 1$,
\[
\sigma_3(m)\,\sigma_3(n)
= \sum_{d \mid \gcd(m,n)} d^3\,\sigma_3\!\left(\frac{mn}{d^2}\right)
= \heckeRHS(m,n).
\]
\end{theorem}
\begin{proof}
Both sides are multiplicative in the pair $(m,n)$, so it suffices to treat
$m = p^a$, $n = p^b$. Then $\gcd(p^a,p^b) = p^{\min(a,b)}$ and, with $q = p^3$
and Theorem~\ref{thm:pp},
\[
\heckeRHS(p^a,p^b) = \sum_{i=0}^{\min(a,b)} q^{i}\sum_{l=0}^{a+b-2i} q^{l}.
\]
The claim becomes the geometric double-sum identity
\[
\Big(\sum_{i=0}^{a} q^{i}\Big)\Big(\sum_{j=0}^{b} q^{j}\Big)
= \sum_{i=0}^{\min(a,b)} q^{i}\sum_{l=0}^{a+b-2i} q^{l},
\]
proved by induction on $\min(a,b)$ via telescoping of geometric series.
Multiplicativity lifts the prime-power case to all $m,n$.
\end{proof}

\begin{remark}[Specializations]
Taking $\gcd(m,n) = 1$ recovers multiplicativity (Theorem~\ref{thm:mult}), and
taking $m = p$, $n = p^{r+1}$ recovers the Hecke recurrence
(Theorem~\ref{thm:rec}).
\end{remark}

\begin{remark}[Interpretation]
In weight $k$, $T_m T_n = \sum_{d \mid \gcd(m,n)} d^{k-1} T_{mn/d^2}$; applied to
$E_4$ with eigenvalues $\sigma_3$ and $k = 4$, this is exactly the convolution
law with $k-1 = 3$.
\end{remark}

\section{Numerical corroboration}

The first shell counts $r(n) = 240\,\sigma_3(n)$ are
\[
\begin{array}{c|cccccccc}
n & 1 & 2 & 3 & 4 & 5 & 6 & 7 & 8\\\hline
\sigma_3(n) & 1 & 9 & 28 & 73 & 126 & 252 & 344 & 585\\
r(n) & 240 & 2160 & 6720 & 17520 & 30240 & 60480 & 82560 & 140400
\end{array}
\]
matching the classical theta coefficients of $E_8$. For instance
$\sigma_3(6) = \sigma_3(2)\sigma_3(3) = 9\cdot 28 = 252$, and at $p=2$, $r=0$ the
recurrence gives $\sigma_3(4) + 8\sigma_3(1) = 73 + 8 = 81 = 9^2 = \sigma_3(2)^2$.

\section{Applications and discussion}

The $240$ minimal vectors of $E_8$ form the root system of $\mathfrak{e}_8$, and
$E_8$ is the densest sphere packing in dimension $8$. Even unimodular lattices
underlie strong error-correcting codes, whose weight distributions are recorded
by the theta series. The identity $\theta_{E_8} = E_4$ is a fully explicit
instance of the automorphic--geometric correspondence organized by the Langlands
program. What makes rank $8$ singularly clean: the genus has a single class,
$M_4$ is one-dimensional, and there are no weight-$4$ cusp forms, so $\sigma_3$
carries the complete Hecke-eigenform structure. Note that it is $\sigma_3$, not
$\rE = 240\,\sigma_3$, that is multiplicative; the scaling produces the factor in
Corollary~\ref{cor:qm}.

\section{Future directions}

\textbf{Weight-8 convolution.} From $\theta_{E_8}^2 = \theta_{E_8 \oplus E_8}$ and
$\dim M_8 = 1$, one expects
$\sigma_7(n) = \sigma_3(n) + 120\sum_{m=1}^{n-1}\sigma_3(m)\sigma_3(n-m)$.

\textbf{Uniqueness of the genus.} Two even unimodular rank-$8$ lattices share all
representation numbers, hence are isometric, since weight-$4$ cusp forms vanish.

\textbf{Ramanujan-type congruences.} From $\sigma_3(p) \equiv 1 + p \pmod{12}$ one
expects $\sigma_3(n) \equiv \sigma_1(n) \pmod{12}$, giving $r(n) \equiv 0
\pmod{2880}$ for prime $n$.

\textbf{Eigenform rigidity.} For odd $k$, $\sigma_k$ should be the unique (up to
scalar) multiplicative $f$ with $f(m)f(n) = \sum_{d \mid \gcd(m,n)} d^k f(mn/d^2)$
and $f(p) = 1 + p^k$.

\section{Conclusion}
The number of $E_8$ vectors of squared length $2n$ is exactly $240\,\sigma_3(n)$:
the Siegel--Weil identity $\theta_{E_8} = E_4$. Beneath it lies a complete
Hecke-eigenform structure, visible purely through divisor sums, making the vector
counts of the most symmetric lattice in dimension $8$ the coefficient system of a
weight-$4$ Hecke eigenform.

