from typing import List

def divisors(n: int) -> List[int]:
    ds = [d for d in range(1, n + 1) if n % d == 0]
    return ds

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def rE8(n: int) -> int:
    """Number of E8 vectors of squared length 2n."""
    return 240 * sigma3(n)

if __name__ == "__main__":
    print("n  sigma_3(n)  r(n)=240*sigma_3(n)")
    for n in range(1, 13):
        print(f"{n:>2}  {sigma3(n):>9}  {rE8(n):>10}")

from math import gcd
from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n)) if n else 0

def hecke_rhs(m: int, n: int) -> int:
    """sum_{d | gcd(m,n)} d^3 * sigma_3(mn / d^2)."""
    g = gcd(m, n)
    return sum(d ** 3 * sigma3(m * n // (d * d)) for d in divisors(g))

if __name__ == "__main__":
    fails = 0
    for m in range(1, 20):
        for n in range(1, 20):
            if sigma3(m) * sigma3(n) != hecke_rhs(m, n):
                fails += 1
    print("Hecke eigenform identity holds for all 1<=m,n<20:", fails == 0)

from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def e8_vector_count(n: int) -> int:
    """Brute-force count of E8 vectors of squared length 2n (small n)."""
    s = 8 * n  # sum of squares of doubled coordinates y = 2x
    bound = int(s ** 0.5)
    count = 0
    def rec(idx: int, rem: int, parity: int, csum: int) -> None:
        nonlocal count
        if idx == 8:
            if rem == 0 and csum % 4 == 0:
                count += 1
            return
        for y in range(-bound, bound + 1):
            if y * y <= rem and y % 2 == parity:
                rec(idx + 1, rem - y * y, parity, csum + y)
    rec(0, s, 0, 0)   # integer points
    rec(0, s, 1, 0)   # half-integer points
    return count

if __name__ == "__main__":
    for n in range(1, 4):
        print(f"n={n}: brute={e8_vector_count(n)}, predicted={240*sigma3(n)}")

