from typing import List

def prime_factorization(n: int) -> List[tuple]:
    """Return list of (prime, exponent) pairs for n >= 1."""
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            e = 0
            while n % d == 0:
                n //= d
                e += 1
            factors.append((d, e))
        d += 1
    if n > 1:
        factors.append((n, 1))
    return factors

def sigma3_fast(n: int) -> int:
    """sigma_3(n) via multiplicativity and the prime-power geometric form:
       sigma_3(p^e) = (p^(3(e+1)) - 1) / (p^3 - 1)."""
    if n < 1:
        raise ValueError("n >= 1 required")
    result = 1
    for p, e in prime_factorization(n):
        result *= (p ** (3 * (e + 1)) - 1) // (p ** 3 - 1)
    return result

