function hecke_convolution(m, n):
    g <- gcd(m, n)
    total <- 0
    for each d dividing g:
        total <- total + d^3 * sigma3(m*n / d^2)
    return total

function sigma3_prime_powers(p, R):
    lam <- 1 + p^3
    vals <- [1, lam]
    for r in 0 .. R-2:
        vals.append(lam * vals[last] - p^3 * vals[last-1])
    return vals[0..R]
